    living = set(living_cells)
    candidates = set(living)
    for cell in living:
        candidates.update(_neighbours(cell))

    survivors = []
    for cell in candidates:
        neighbours = sum(1 for n in _neighbours(cell) if n in living)
        if neighbours == 3 or (neighbours == 2 and cell in living):
            survivors.append(cell)
    return survivors


def _neighbours(cell):
    return [
        Cell(cell.x + dx, cell.y + dy)
        for dx in (-1, 0, 1)
        for dy in (-1, 0, 1)
        if (dx, dy) != (0, 0)
    ]
